<script>
(function(){
var _cs = document.currentScript;
function el(tag, attrs, txt){
  var e = document.createElementNS("http://www.w3.org/2000/svg", tag);
  for (var k in attrs){ e.setAttribute(k, attrs[k]); }
  if (txt !== undefined && txt !== null){ e.textContent = txt; }
  return e;
}
var dates = ["Jun 24","Jun 25","Jun 26","Jun 29","Jun 30","Jul 2","Jul 3","Jul 7","Jul 8","Jul 9","Jul 10","Jul 13"];
var gold  = [4190,4150,4110,4070,4031,4080,4163,4145,4125,4110,4100,4063.91];
var ust10 = [4.42,4.44,4.46,4.47,4.48,4.49,4.50,4.50,4.60,4.56,4.54,4.59];
var n = dates.length;

var margin = {left:62, right:24, top:18, bottom:46};
var PW = 594, PH = 236;
var goldMin = 3950, goldMax = 4250;
var ustMin = 4.30, ustMax = 4.70;

function xp(i){ return margin.left + i * (PW/(n-1)); }
function ypGold(v){ return margin.top + (goldMax - v)/(goldMax-goldMin) * PH; }
function ypUst(v){ return margin.top + (ustMax - v)/(ustMax-ustMin) * PH; }

var svg = document.createElementNS("http://www.w3.org/2000/svg","svg");
svg.setAttribute("viewBox","0 0 680 300");

// Gridlines (horizontal, left axis reference)
for (var g=0; g<=4; g++){
  var gv = goldMin + g*(goldMax-goldMin)/4;
  var gy = ypGold(gv);
  svg.appendChild(el("line",{x1:margin.left,x2:margin.left+PW,y1:gy,y2:gy,stroke:"#ececec","stroke-width":"0.5"}));
  svg.appendChild(el("text",{x:margin.left-6,y:gy+3,"text-anchor":"end","font-size":"8.5","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif",fill:"#aaaaaa"}, "$"+Math.round(gv)));
}
// Right axis labels (UST10Y)
for (var u=0; u<=4; u++){
  var uv = ustMin + u*(ustMax-ustMin)/4;
  var uy = ypUst(uv);
  svg.appendChild(el("text",{x:margin.left+PW-4,y:uy+3,"text-anchor":"start","font-size":"8.5","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif",fill:"#aaaaaa"}, uv.toFixed(2)+"%"));
}

// Axis lines
svg.appendChild(el("line",{x1:margin.left,x2:margin.left,y1:margin.top,y2:margin.top+PH,stroke:"#d8d8d8","stroke-width":"1"}));
svg.appendChild(el("line",{x1:margin.left,x2:margin.left+PW,y1:margin.top+PH,y2:margin.top+PH,stroke:"#d8d8d8","stroke-width":"1"}));

// X-axis labels (every other point to avoid crowding)
for (var i=0;i<n;i++){
  if (i % 2 === 0 || i === n-1){
    svg.appendChild(el("text",{x:xp(i),y:margin.top+PH+16,"text-anchor":"middle","font-size":"8","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif",fill:"#999999"}, dates[i]));
  }
}

// Event marker line at Jul 7 (index 7)
var evX = xp(7);
svg.appendChild(el("line",{x1:evX,x2:evX,y1:margin.top,y2:margin.top+PH,stroke:"#1a3560","stroke-opacity":"0.5","stroke-dasharray":"2,3"}));
svg.appendChild(el("text",{x:evX+3,y:margin.top+12,"text-anchor":"start","font-size":"7","font-weight":"700","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif",fill:"#1a3560"}, "TANKER ATTACK,"));
svg.appendChild(el("text",{x:evX+3,y:margin.top+21,"text-anchor":"start","font-size":"7","font-weight":"700","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif",fill:"#1a3560"}, "LICENCE REVOKED"));

// Gold price line (slate blue-grey, primary series)
var goldPath = "M" + xp(0) + "," + ypGold(gold[0]);
for (var i2=1;i2<n;i2++){ goldPath += " L" + xp(i2) + "," + ypGold(gold[i2]); }
svg.appendChild(el("path",{d:goldPath, fill:"none", stroke:"#4a5568", "stroke-width":"1.8"}));

// UST10Y line (dashed grey, secondary/overlay series)
var ustPath = "M" + xp(0) + "," + ypUst(ust10[0]);
for (var i3=1;i3<n;i3++){ ustPath += " L" + xp(i3) + "," + ypUst(ust10[i3]); }
svg.appendChild(el("path",{d:ustPath, fill:"none", stroke:"#888888", "stroke-width":"1.5", "stroke-dasharray":"4,3"}));

// End of series labels
svg.appendChild(el("text",{x:xp(n-1)-2,y:ypGold(gold[n-1])-8,"text-anchor":"start","font-size":"7.5","font-weight":"700","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif",fill:"#4a5568"}, "GOLD"));
svg.appendChild(el("text",{x:xp(n-1)-4,y:ypUst(ust10[n-1])-8,"text-anchor":"end","font-size":"7.5","font-weight":"700","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif",fill:"#888888"}, "UST 10Y"));

// Gold pill callout on final gold value (left of endpoint, dot decoupled)
var lastX = xp(n-1), lastY = ypGold(gold[n-1]);
var pillW = 62, pillH = 16;
var pillX = lastX - pillW - 6;
var pillY = lastY - pillH/2 - 14;
if (pillX < margin.left) pillX = lastX + 6;
svg.appendChild(el("circle",{cx:lastX, cy:lastY, r:4, fill:"#4a5568"}));
svg.appendChild(el("rect",{x:pillX, y:pillY, width:pillW, height:pillH, rx:3, fill:"#e8a825"}));
svg.appendChild(el("text",{x:pillX+pillW/2, y:pillY+pillH/2+4, "text-anchor":"middle","font-size":"9","font-weight":"700","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif",fill:"#111111"}, "$4,063.91"));

var container = _cs ? _cs.parentNode : null;
if (container) container.appendChild(svg);
