  return e;
}
var cats = ["Steel, wholly of","Aluminum, wholly of","Copper, wholly of","Autos and auto parts","Steel/alum derivatives","Kitchen cabinets, vanities","Upholstered furniture","Softwood lumber, timber"];
var rates = [50,50,50,25,25,25,25,10];
var cusmaCarve = [false,false,false,true,false,false,false,false];
var n = cats.length;

var margin = {left:150, right:60, top:18, bottom:30};
var PW = 470, PH = 252;
var barGap = 8;
var barH = (PH - barGap*(n-1)) / n;
var maxRate = 55;

function xp(v){ return margin.left + (v/maxRate) * PW; }
function yBar(i){ return margin.top + i*(barH+barGap); }

var svg = document.createElementNS("http://www.w3.org/2000/svg","svg");
svg.setAttribute("viewBox","0 0 680 300");

// Gridlines vertical (0,10,25,50)
[0,10,25,50].forEach(function(v){
  var gx = xp(v);
  svg.appendChild(el("line",{x1:gx,x2:gx,y1:margin.top,y2:margin.top+PH,stroke:"#ececec","stroke-width":"0.5"}));
  svg.appendChild(el("text",{x:gx,y:margin.top+PH+13,"text-anchor":"middle","font-size":"8","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif",fill:"#999999"}, v+"%"));
});

for (var i=0;i<n;i++){
  var y = yBar(i);
  var w = xp(rates[i]) - margin.left;
  var fillColor = rates[i] >= 50 ? "#8a3030" : (rates[i] >= 25 ? "#4a5568" : "#9ca3af");
  svg.appendChild(el("rect",{x:margin.left, y:y, width:w, height:barH, fill:fillColor}));
  // category label left of bar
  svg.appendChild(el("text",{x:margin.left-6, y:y+barH/2+3, "text-anchor":"end","font-size":"8","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif",fill:"#444444"}, cats[i]));
  // value label at bar end
  var txtColor = "#444444";
  svg.appendChild(el("text",{x:xp(rates[i])+6, y:y+barH/2+3, "text-anchor":"start","font-size":"8.5","font-weight":"700","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif",fill:txtColor}, rates[i]+"%"));
  if (cusmaCarve[i]){
    svg.appendChild(el("text",{x:xp(rates[i])+30, y:y+barH/2+3, "text-anchor":"start","font-size":"7","font-weight":"700","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif",fill:"#2e7d32"}, "CUSMA CARVE OUT AVAILABLE"));
  }
}

// axis line
svg.appendChild(el("line",{x1:margin.left,x2:margin.left,y1:margin.top,y2:margin.top+PH,stroke:"#d8d8d8","stroke-width":"1"}));

// Gold pill callout on the most significant value (Steel, the ceiling rate)
// Placed left of the bar endpoint per pill placement convention, dot decoupled at true endpoint
var pillW = 102, pillH = 16;
var steelBarEndX = xp(rates[0]);
var steelY = yBar(0) + barH/2;
var pillX = steelBarEndX - pillW - 8;
var pillY = steelY - pillH/2;
if (pillX < margin.left) pillX = steelBarEndX + 6;
svg.appendChild(el("circle",{cx:steelBarEndX, cy:steelY, r:3, fill:"#ffffff"}));
svg.appendChild(el("rect",{x:pillX, y:pillY, width:pillW, height:pillH, rx:3, fill:"#e8a825"}));
svg.appendChild(el("text",{x:pillX+pillW/2, y:pillY+pillH/2+4, "text-anchor":"middle","font-size":"8","font-weight":"700","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif",fill:"#111111"}, "SECTION 232 CEILING"));

var container = _cs ? _cs.parentNode : null;
if (container) container.appendChild(svg);
})();
</script>
</div>
<div style="font-family:-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif;font-size:10px;color:#999;padding:4px 14px 10px;font-style:italic;">Source: Global Affairs Canada trade commissioner tariff guidance and Congressional Research Service IN12519, current as of July 2026. &nbsp;|&nbsp; hdq.ca</div>
</div>
</div>
<p style="font-size:11px;color:#666;font-family:-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif;margin-top:6px;">Rates shown apply on the full customs value for wholly metal articles and on metal content for derivative products. Softwood lumber carries an additional 14.18% combined anti dumping and countervailing duty rate not reflected here.</p>',
  '<div class="toolkit-section">
<div class="toolkit-section-label">What They''re Feeling</div>
<p>Business owner clients are tired of trade headlines and increasingly numb to them, which is its own risk. After more than a year of tariff news, the instinct is to assume this is more of the same and not read closely enough to see that the planning horizon itself just changed from six years to twelve months.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">What to Say</div>
<div class="script-box">CUSMA did not end on July 1, and your existing duty treatment has not changed. What changed is smaller but still matters for you. The agreement used to guarantee a review every six years. Now it gets reviewed every year until the parties agree to extend it, possibly for the next decade. That does not mean new tariffs are coming. It means the assumption you have been building your cross border plans around, a stable multi year rules environment, is no longer accurate. I want to make sure your origin documentation and transfer pricing files are current, because that is the part of this you can control regardless of how the reviews go.</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Who''s Affected</div>
<p><strong>High impact:</strong> CCPC owners with cross border supply chains relying on CUSMA''s zero duty treatment, particularly in auto parts, agriculture, and general manufacturing.</p>
<p><strong>Mixed impact:</strong> CCPC owners already paying Section 232 tariffs on steel, aluminum, copper, or lumber, who have less CUSMA relief at stake but still face rules of origin scrutiny on any CUSMA compliant portion of their business.</p>
<p><strong>Potential benefit:</strong> Clients in industries the government is actively protecting through remission orders and extended surtax exemptions, including the auto and aerospace sectors through July 2027.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Action Checklist</div>
<div class="checklist-item">Identify CCPC clients with cross border trade exposure and flag files for a documentation review this quarter</div>
<div class="checklist-item">Confirm each flagged client has current rules of origin and transfer pricing support, not documentation reconstructed after the fact</div>
<div class="checklist-item">Note the July 1, 2027 Steel Derivative Goods Surtax Order deadline on any auto or aerospace sector client file</div>
<div class="checklist-item">Flag any client considering US facing capital expansion this year for a conversation about building contingency into the timeline</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Follow-Up Email Template</div>
<div class="email-box" id="respond-email">
<strong>Subject:</strong> What the CUSMA review actually means for your business<br><br>
Hi [Client Name],<br><br>
Following our call, here is the short version. CUSMA was not renewed for a new sixteen year term on July 1, but it also was not terminated. The practical change is that the agreement now faces annual reviews instead of the original six year cycle, for as long as it takes the three countries to agree on an extension.<br><br>
Nothing in your current duty treatment has changed today. The action item is making sure your rules of origin and transfer pricing documentation is current, since that is the area most likely to face closer scrutiny going forward. I would like to schedule time to review your file specifically.<br><br>
[Your Name]<br><br>
<em>This communication is for educational purposes only and does not constitute personalized investment advice.</em>
</div>
<button class="btn-copy" onclick="copyEmail(''respond-email'', this)">Copy email</button>
</div>',
  '<div class="toolkit-section">
<div class="toolkit-section-label">Client Profiles to Target</div>
<p><strong>CCPC owners with US exposure:</strong> Business owners currently relying on an accountant or bookkeeper for trade compliance rather than a coordinated advisory relationship.</p>
<p><strong>Auto and aerospace sector owners:</strong> Businesses with a hard July 2027 deadline on the surtax exemption who may not have a plan beyond that date yet.</p>
<p><strong>Owners weighing US facing expansion:</strong> Business owners currently evaluating capital investment decisions who have not factored the shortened CUSMA review cycle into their planning.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Opening Line</div>
<div class="script-box">Did you catch that CUSMA is now reviewed annually instead of every six years. If your business has any cross border exposure, that is a bigger change to your planning horizon than most of the tariff headlines from the past year.</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Value Proposition</div>
<p>A business owner managing trade exposure alone typically has a bookkeeper handling compliance and no one connecting the trade policy calendar to the broader financial plan. The advisor''s value here is coordination: knowing that the CUSMA review cycle just compressed from six years to one, knowing which specific deadlines apply to which sectors, and translating that into concrete guidance on documentation and capital planning timing before a decision gets made on outdated assumptions.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Discovery Questions</div>
<p>Does your business currently rely on CUSMA''s duty free treatment for any part of your supply chain?</p>
<p>Who is responsible for your rules of origin and transfer pricing documentation, and when was it last updated?</p>
<p>Are you planning any US facing capital investment in the next two years, and has that planning accounted for annual trade policy reviews rather than a six year cycle?</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Prospecting Email Template</div>
<div class="email-box" id="prospect-email">
<strong>Subject:</strong> CUSMA''s review cycle just changed. Does your business plan account for it.<br><br>
Hi [Name],<br><br>
On July 1, the United States declined to extend CUSMA for a new sixteen year term. The agreement remains in force, but it now faces annual reviews instead of the original six year cycle, for as long as it takes to reach an extension.<br><br>
If your business has any cross border exposure, this is worth thirty minutes to discuss, particularly around documentation and the timing of any US facing capital plans. I would be glad to walk through what it means for your specific situation.<br><br>
[Your Name]<br><br>
<em>This communication is for educational purposes only and does not constitute personalized investment advice.</em>
</div>
<button class="btn-copy" onclick="copyEmail(''prospect-email'', this)">Copy email</button>
</div>',
  '[{"value":"16","label":"Years of extension declined"},{"value":"2027","label":"Extended surtax exemption deadline"},{"value":"76%","label":"Canadian exports going to US"},{"value":"2036","label":"CUSMA''s current term expiry"}]',
  'tax-052.jpg',
  'Cross border trade policy uncertainty is shaping planning conversations for Canadian business owners with exposure to the US market. Photo: iStock.',
