<script>
(function(){
var _cs = document.currentScript;
function el(tag, attrs, txt){
  var e = document.createElementNS("http://www.w3.org/2000/svg", tag);
  for (var k in attrs){ e.setAttribute(k, attrs[k]); }
  if (txt !== undefined && txt !== null){ e.textContent = txt; }
  return e;
}
var dates = ["Jun 22","Jun 23","Jun 24","Jun 25","Jun 26","Jun 29","Jun 30","Jul 2","Jul 3","Jul 7","Jul 8","Jul 10"];
var tsx = [35400,35250,35100,34980,34900,34870,34857,34950,35080,35299.67,35280,35305.31];
var n = dates.length;
var athVal = 35629.89;

var margin = {left:66, right:24, top:26, bottom:46};
var PW = 590, PH = 228;
var priceMin = 34600, priceMax = 35750;

function xp(i){ return margin.left + i * (PW/(n-1)); }
function yp(v){ return margin.top + (priceMax - v)/(priceMax-priceMin) * PH; }

var svg = document.createElementNS("http://www.w3.org/2000/svg","svg");
svg.setAttribute("viewBox","0 0 680 300");

for (var g=0; g<=4; g++){
  var gv = priceMin + g*(priceMax-priceMin)/4;
  var gy = yp(gv);
  svg.appendChild(el("line",{x1:margin.left,x2:margin.left+PW,y1:gy,y2:gy,stroke:"#ececec","stroke-width":"0.5"}));
  svg.appendChild(el("text",{x:margin.left-6,y:gy+3,"text-anchor":"end","font-size":"8.5","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif",fill:"#aaaaaa"}, Math.round(gv).toLocaleString()));
}

svg.appendChild(el("line",{x1:margin.left,x2:margin.left,y1:margin.top,y2:margin.top+PH,stroke:"#d8d8d8","stroke-width":"1"}));
svg.appendChild(el("line",{x1:margin.left,x2:margin.left+PW,y1:margin.top+PH,y2:margin.top+PH,stroke:"#d8d8d8","stroke-width":"1"}));

for (var i=0;i<n;i++){
  svg.appendChild(el("text",{x:xp(i),y:margin.top+PH+16,"text-anchor":"middle","font-size":"8","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif",fill:"#999999"}, dates[i]));
}

// Reference line: June 17 all-time high (resistance, green dashed)
var athY = yp(athVal);
svg.appendChild(el("line",{x1:margin.left,x2:margin.left+PW,y1:athY,y2:athY,stroke:"#2e7d32","stroke-dasharray":"3,3"}));
svg.appendChild(el("text",{x:margin.left+PW-4,y:athY-4,"text-anchor":"end","font-size":"7.5","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif",fill:"#2e7d32"}, "JUN 17 RECORD, 35,629.89"));

// Event marker: Jul 7 tanker attack
var ev1 = xp(9);
svg.appendChild(el("line",{x1:ev1,x2:ev1,y1:margin.top,y2:margin.top+PH,stroke:"#1a3560","stroke-opacity":"0.5","stroke-dasharray":"2,3"}));
svg.appendChild(el("text",{x:ev1-4,y:margin.top+10,"text-anchor":"end","font-size":"7","font-weight":"700","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif",fill:"#1a3560"}, "TANKER ATTACK"));

// TSX line
var path = "M" + xp(0) + "," + yp(tsx[0]);
for (var i2=1;i2<n;i2++){ path += " L" + xp(i2) + "," + yp(tsx[i2]); }
svg.appendChild(el("path",{d:path, fill:"none", stroke:"#4a5568", "stroke-width":"2"}));

for (var i3=0;i3<n;i3++){
  svg.appendChild(el("circle",{cx:xp(i3),cy:yp(tsx[i3]),r:2.3,fill:"#4a5568"}));
}

// End of series label
svg.appendChild(el("text",{x:xp(n-1)-4,y:yp(tsx[n-1])+16,"text-anchor":"end","font-size":"7.5","font-weight":"700","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif",fill:"#4a5568"}, "TSX"));

// Gold pill callout, left of endpoint, dot decoupled
var lastX = xp(n-1), lastY = yp(tsx[n-1]);
var pillW = 70, pillH = 16;
var pillX = lastX - pillW - 6;
var pillY = lastY - pillH/2 - 12;
if (pillX < margin.left) pillX = lastX + 6;
svg.appendChild(el("circle",{cx:lastX, cy:lastY, r:4, fill:"#4a5568"}));
svg.appendChild(el("rect",{x:pillX, y:pillY, width:pillW, height:pillH, rx:3, fill:"#e8a825"}));
svg.appendChild(el("text",{x:pillX+pillW/2, y:pillY+pillH/2+4, "text-anchor":"middle","font-size":"8.5","font-weight":"700","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif",fill:"#111111"}, "35,305.31"));

var container = _cs ? _cs.parentNode : null;
if (container) container.appendChild(svg);
})();
</script>
